import{_ as e,c as r,o as i,af as n}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"23、【剝】 坤下艮上","description":"溫公易說 - 23、【剝】 坤下艮上","frontmatter":{"title":"23、【剝】 坤下艮上","description":"溫公易說 - 23、【剝】 坤下艮上"},"headers":[],"relativePath":"classics/wengong/024.md","filePath":"classics/wengong/024.md"}'),l={name:"classics/wengong/024.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_23、【剝】-坤下艮上" tabindex="-1">23、【剝】 坤下艮上 <a class="header-anchor" href="#_23、【剝】-坤下艮上" aria-label="Permalink to “23、【剝】 坤下艮上”">​</a></h1><h3 id="彖曰-剝-剝也-柔變剛也。不利有攸往-小人長也。順而止之-觀象也。君子尚消息盈虛-天行也。" tabindex="-1">彖曰：剝，剝也，柔變剛也。不利有攸往，小人長也。順而止之，觀象也。君子尚消息盈虛，天行也。 <a class="header-anchor" href="#彖曰-剝-剝也-柔變剛也。不利有攸往-小人長也。順而止之-觀象也。君子尚消息盈虛-天行也。" aria-label="Permalink to “彖曰：剝，剝也，柔變剛也。不利有攸往，小人長也。順而止之，觀象也。君子尚消息盈虛，天行也。”">​</a></h3><h3 id="象曰-山附於地-剝。上以厚下安宅。" tabindex="-1">象曰：山附於地，剝。上以厚下安宅。 <a class="header-anchor" href="#象曰-山附於地-剝。上以厚下安宅。" aria-label="Permalink to “象曰：山附於地，剝。上以厚下安宅。”">​</a></h3><p>剝以厚下安宅，夫基薄則牆隤，下薄則上危。故君子厚其下者，所以自安其居也。</p><h3 id="初六-剝床以足-蔑貞兇-象曰-剝床以足-以滅下也。" tabindex="-1">初六：剝床以足，蔑貞兇 象曰：剝床以足，以滅下也。 <a class="header-anchor" href="#初六-剝床以足-蔑貞兇-象曰-剝床以足-以滅下也。" aria-label="Permalink to “初六：剝床以足，蔑貞兇 象曰：剝床以足，以滅下也。”">​</a></h3><h3 id="六二-剝床以辨-蔑貞兇-象曰-剝床以辨-未有與也。" tabindex="-1">六二：剝床以辨，蔑貞兇 象曰：剝床以辨，未有與也。 <a class="header-anchor" href="#六二-剝床以辨-蔑貞兇-象曰-剝床以辨-未有與也。" aria-label="Permalink to “六二：剝床以辨，蔑貞兇 象曰：剝床以辨，未有與也。”">​</a></h3><h3 id="六三-剝之-無咎-象曰-剝之無咎-失上下也。" tabindex="-1">六三：剝之，無咎 象曰：剝之無咎，失上下也。 <a class="header-anchor" href="#六三-剝之-無咎-象曰-剝之無咎-失上下也。" aria-label="Permalink to “六三：剝之，無咎 象曰：剝之無咎，失上下也。”">​</a></h3><h3 id="六四-剝床以膚-兇-象曰-剝床以膚-切近災也。" tabindex="-1">六四：剝床以膚，兇 象曰：剝床以膚，切近災也。 <a class="header-anchor" href="#六四-剝床以膚-兇-象曰-剝床以膚-切近災也。" aria-label="Permalink to “六四：剝床以膚，兇 象曰：剝床以膚，切近災也。”">​</a></h3><h3 id="六五-貫魚-以宮人寵-無不利-象曰-以宮人寵-終無尤也。" tabindex="-1">六五：貫魚，以宮人寵，無不利 象曰：以宮人寵，終無尤也。 <a class="header-anchor" href="#六五-貫魚-以宮人寵-無不利-象曰-以宮人寵-終無尤也。" aria-label="Permalink to “六五：貫魚，以宮人寵，無不利 象曰：以宮人寵，終無尤也。”">​</a></h3><h3 id="上九-碩果不食-君子得輿-小人剝廬-象曰-君子得輿-民所載也。小人剝廬-終不可用也。" tabindex="-1">上九：碩果不食，君子得輿，小人剝廬 象曰：君子得輿，民所載也。小人剝廬，終不可用也。 <a class="header-anchor" href="#上九-碩果不食-君子得輿-小人剝廬-象曰-君子得輿-民所載也。小人剝廬-終不可用也。" aria-label="Permalink to “上九：碩果不食，君子得輿，小人剝廬 象曰：君子得輿，民所載也。小人剝廬，終不可用也。”">​</a></h3><p>碩果不食，將墜於地而復生也。剝之為道，舉卦皆陰而上獨以陽乘之，猶衰世之君子獨立不懼，以制群陰。雖不當位，民所載也。或者陰來伐之，則是小人得志，君子道窮，禍亂遂成，民無所庇矣。詩云：人之雲亡，邦國殄瘁，此之謂也。</p>',11)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
